  function getGoals() {
    if (!storage) return [];
    return storage.get('goals') || [];
  }

  function addGoal(title) {
    if (!storage) return null;
    const goals = getGoals();
    const newGoal = { id: 'goal-' + Date.now(), title, completed: false, createdAt: new Date().toISOString() };
    storage.set('goals', [...goals, newGoal]);
    return newGoal;
  }

  function toggleGoal(id) {
    if (!storage) return;
    const goals = getGoals();
    const updated = goals.map(g => g.id === id ? { ...g, completed: !g.completed } : g);
    storage.set('goals', updated);
  }

  function deleteGoal(id) {
    if (!storage) return;
    const goals = getGoals();
    const updated = goals.filter(g => g.id !== id);
    storage.set('goals', updated);
  }

  return { getGoals, addGoal, toggleGoal, deleteGoal };
}

