    const today = new Date().toISOString().split('T')[0];
    if (action === 'increment') {
      if (streak.lastCompletedDate === today) return streak;
      const updated = {
        currentStreak: streak.currentStreak + 1,
        lastCompletedDate: today
      };
      personalStorage.set('streak', updated);
      return updated;
    }
    if (action === 'reset') {
      const updated = { currentStreak: 0, lastCompletedDate: null };
      personalStorage.set('streak', updated);
      return updated;
    }
    return streak;
  }

  return { getState, execute };
}

